<?php
// Quiosque público: a identidade é definida exclusivamente pela face cadastrada.
require_once __DIR__ . '/../../includes/config.php';
$requestPath = parse_url($_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH) ?: '';
if (substr($requestPath, -strlen('/modules/ponto/ponto_publico.php')) === '/modules/ponto/ponto_publico.php') {
    $canonicalBase = defined('SITE_URL') && SITE_URL !== ''
        ? rtrim(SITE_URL, '/')
        : ((isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' ? 'https' : 'http') . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . rtrim(BASE_URL, '/'));
    header('Location: ' . $canonicalBase . '/ponto-publico?' . http_build_query($_GET));
    exit;
}
$empresaId = (int) ($_GET['empresa'] ?? 0);
$chave = (string) ($_GET['chave'] ?? '');
$esperada = $empresaId > 0 ? hash_hmac('sha256', (string) $empresaId, DB_PASS . '|ponto-publico') : '';
if ($empresaId <= 0 || $chave === '' || !hash_equals($esperada, $chave)) {
    http_response_code(403);
    exit('Link público inválido. Gere um novo link no painel da empresa.');
}
?>
