body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:var(--pf-gradient);font-family:var(--bs-font-sans-serif);color:var(--text-primary)}.card{width:min(100%,500px);overflow:hidden;background:var(--bg-primary);border:1px solid var(--border-color);border-radius:22px;box-shadow:0 24px 70px #0f172a40;text-align:center}.card-head{padding:28px 24px 24px;background:var(--pf-gradient);color:#fff}.card-head .brand{font-size:38px}.card-head h1{margin:8px 0 4px;color:#fff;font-size:24px}.card-head p{margin:0;color:#e0e7ff}.card-body{padding:24px}.hint{color:var(--text-secondary);line-height:1.5;margin:0 0 20px}.camera{position:relative;aspect-ratio:4/3;overflow:hidden;border-radius:16px;background:#111827;margin:0 0 16px}.camera video{width:100%;height:100%;object-fit:cover;transform:scaleX(-1)}.guide{position:absolute;inset:15% 25%;border:3px solid #ffffffbb;border-radius:48%;box-shadow:0 0 0 999px #0003}.status{min-height:48px;padding:13px;border-radius:12px;background:color-mix(in srgb,var(--pf-primary) 10%,var(--bg-secondary));color:var(--pf-primary);font-weight:700}.status.error{background:#fef2f2;color:#b91c1c}.status.success{background:#ecfdf5;color:#047857}.button{width:100%;padding:15px;border:0;border-radius:12px;background:var(--pf-gradient);color:#fff;font-size:16px;font-weight:800;cursor:pointer;margin-top:16px}.button.secondary{background:var(--bg-secondary);color:var(--pf-primary);border:1px solid var(--border-color)}.button:disabled{opacity:.55;cursor:wait}.privacy{font-size:12px;color:var(--text-muted);margin:18px 0 0}
